const d = $('Pro Nutzer').first().json;
const heute = DateTime.now().setZone('Europe/Berlin');
const esc = s => String(s ?? '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const euro = v => (v === null || v === undefined || v === '') ? '' : Number(v).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });

// Termine (Kalender des Nutzers)
const termine = $('Termine heute').all().map(i => i.json).filter(e => e && e.id && e.start);
const kalenderFehler = !d.kalender_id || $('Termine heute').all().some(i => i.json && i.json.error);
const zeit = e => e.start && e.start.dateTime ? DateTime.fromISO(e.start.dateTime).setZone('Europe/Berlin').toFormat('HH:mm') + '–' + DateTime.fromISO(e.end.dateTime).setZone('Europe/Berlin').toFormat('HH:mm') : 'ganztägig';

const klaerungen = Array.isArray(d.klaerungen) ? d.klaerungen : [];
const mails = Array.isArray(d.mails) ? d.mails : [];
const geschaeft = Array.isArray(d.geschaeft) ? d.geschaeft : [];
const vorname = String(d.anzeigename || '').split(' ')[0];

// Aufbau: Abschnitte mit Inhalt, getrennt durch Leerzeilen (Handy und Desktop); keine Aufzaehlungslisten, keine Emojis.
// Zeile = { t: Text, kursiv: bool }
const abschnitte = [];
const nichts = [];
const abschnitt = (titel, zeilen) => abschnitte.push({ titel, zeilen });
const mailZeilen = m => [
  { t: (m.zeitkritisch ? 'Frist · ' : '') + (m.absender || '?') + (m.anhang ? ' (mit Anhang)' : '') },
  { t: m.betreff || '(ohne Betreff)', kursiv: true }
];

if (!d.kalender_id) abschnitt('Termine heute', [{ t: 'Kein Kalender hinterlegt.' }]);
else if (kalenderFehler && !termine.length) abschnitt('Termine heute', [{ t: 'Kalender war nicht abrufbar.' }]);
else if (termine.length) abschnitt('Termine heute', termine.map(e => ({ t: zeit(e) + ' · ' + (e.summary || '(ohne Titel)') + (e.location ? ' · ' + e.location : '') })));
else nichts.push('Keine Termine');

if (mails.length) abschnitt('Mails der Kundschaft und Fristen (24 h)', mails.flatMap(mailZeilen));
else nichts.push('Keine Mails der Kundschaft oder Fristen');

if (geschaeft.length) abschnitt('evtl. Wichtig (24h)', geschaeft.flatMap(mailZeilen));
else nichts.push('Keine geschäftlichen Mails');

if (d.zeige_klaerungen) {
  // Grund der Klärung lesbar mit ausgeben (Stefan 17.10.2026)
  const grundText = { lieferant_unklar: 'Lieferant unklar', kategorie_unklar: 'Angaben unsicher', moeglicher_duplikat: 'Möglicherweise doppelt', relevanz_unklar: 'Relevanz unklar' };
  if (klaerungen.length) abschnitt('Offene Klärungsfälle', klaerungen.map(k => ({ t: 'klaerung-' + k.id + ' · ' + (k.lieferant || k.absender || '?') + (k.betrag ? ' · ' + euro(k.betrag) : '') + (grundText[k.grund] ? ' · ' + grundText[k.grund] : '') })));
  else nichts.push('Keine Klärungsfälle');
}

if (nichts.length) abschnitt('Sonst nichts offen', nichts.map(t => ({ t })));

const kopfHtml = '<strong>Guten Morgen' + (vorname ? ', ' + esc(vorname) : '') + '.</strong><br>' + esc(heute.setLocale('de').toFormat('cccc, d. LLLL'));
const kopfText = 'Guten Morgen' + (vorname ? ', ' + vorname : '') + '.\n' + heute.setLocale('de').toFormat('cccc, d. LLLL');
const html = [kopfHtml].concat(abschnitte.map(a => '<strong>' + esc(a.titel) + ':</strong><br>' + a.zeilen.map(z => z.kursiv ? '<em>' + esc(z.t) + '</em>' : esc(z.t)).join('<br>'))).join('<br><br>');
const text = [kopfText].concat(abschnitte.map(a => a.titel + ':\n' + a.zeilen.map(z => z.t).join('\n'))).join('\n\n');

return [{ json: { matrix_user_id: d.matrix_user_id, room_id: d.room_id, text, html, ueberfaellig: 0 } }];

// Sofort-Briefing (Start durch Ally): nur die angefragte Person, sonst alle fälligen
const nur = $('Start durch Ally').isExecuted ? String(($('Start durch Ally').first().json || {}).nutzer || '').trim() : '';
if ($('Start durch Ally').isExecuted && !nur) return [];
return $('Fällige Nutzer laden').all().filter(i => !nur || i.json.matrix_user_id === nur).map(i => ({ json: i.json }));

